insert into public.questions (id, kind, prompt, options, marks, image_url) values ('a2e6a6be-afb7-5d9e-bccc-b0acebb20c4a', 'short', 'Explain how climate change can disrupt the synchrony between a bird and its insect prey.', '[]'::jsonb, 3, 'https://commons.wikimedia.org/wiki/Special:FilePath/Great_tit_feeding_chick_retuschiert.jpg?width=900') on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = excluded.image_url;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('a2e6a6be-afb7-5d9e-bccc-b0acebb20c4a', 'Warmer springs make insects emerge earlier, cued by temperature [1]; birds timing breeding by photoperiod do not shift as much [1]; chicks hatch after the insect peak, so there is less food and breeding success falls [1].', 'Warmer springs make insects emerge earlier, cued by temperature [1]; birds timing breeding by photoperiod do not shift as much [1]; chicks hatch after the insect peak, so there is less food and breeding success falls [1].', '[{"text": "Marking point 1", "any": ["temperature", "warmer", "earlier"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["photoperiod", "day length", "different cue"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["mismatch", "less food", "after the peak", "chicks"], "all": [], "marks": 1}]'::jsonb, 'Warmer springs make insects emerge earlier, cued by temperature [1]; birds timing breeding by photoperiod do not shift as much [1]; chicks hatch after the insect peak, so there is less food and breeding success falls [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
