insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('630c9775-0eff-5db0-84b9-37dfa66543fc', 'Warmer, longer summers speed up development so beetles complete more generations per year [1]; milder winters also let more survive, so populations explode and kill more trees [1].', 'Warmer, longer summers speed up development so beetles complete more generations per year [1]; milder winters also let more survive, so populations explode and kill more trees [1].', '[{"text": "Marking point 1", "any": ["faster development", "more generations", "two generations", "life cycles"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["warmer", "longer season", "milder winter", "survive"], "all": [], "marks": 1}]'::jsonb, 'Warmer, longer summers speed up development so beetles complete more generations per year [1]; milder winters also let more survive, so populations explode and kill more trees [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
