insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('6c7f5f9a-1f59-5e96-9b13-7cca77192d5d', 'Warming increases drought, wildfires and insect outbreaks in boreal forests [1]; trees die and burn, releasing more carbon than photosynthesis absorbs, so there is net carbon loss [1].', 'Warming increases drought, wildfires and insect outbreaks in boreal forests [1]; trees die and burn, releasing more carbon than photosynthesis absorbs, so there is net carbon loss [1].', '[{"text": "Marking point 1", "any": ["fire", "drought", "pest", "insect"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["release", "more than absorb", "net loss", "die"], "all": [], "marks": 1}]'::jsonb, 'Warming increases drought, wildfires and insect outbreaks in boreal forests [1]; trees die and burn, releasing more carbon than photosynthesis absorbs, so there is net carbon loss [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
